(* [comment removed for export] *)
Ltac cnt_idx b idx BR bnd v RD V m tab ws UA UAL TOK :=
  set (b := idx) in *; assert (BR : 0 <= b <= 255) by (subst b; bnd); clearbody b;
  destruct (tab_lookup m tab ws b UA UAL TOK BR) as (v & RD & V).
Ltac cnt_b0 y b BR v RD V m tab ws UA UAL TOK :=
  rewrite (land_255 y);
  cnt_idx b (y mod 256) BR ltac:(pose proof (Z.mod_pos_bound y 256 ltac:(lia)); lia) v RD V m tab ws UA UAL TOK.
Ltac cnt_b12 y d b BR v RD V m tab ws UA UAL TOK :=
  rewrite (land_1020 (y / d));
  cnt_idx b ((y / d) mod 1024 / 4) BR ltac:(pose proof (Z.mod_pos_bound (y / d) 1024 ltac:(lia)); Z.div_mod_to_equations; lia) v RD V m tab ws UA UAL TOK.
Ltac cnt_b3 y Y0 b BR v RD V m tab ws UA UAL TOK :=
  rewrite (srliw_24 y Y0);
  cnt_idx b ((y mod 2^32) / 16777216) BR ltac:(pose proof (Z.mod_pos_bound y (2^32) ltac:(lia)); Z.div_mod_to_equations; lia) v RD V m tab ws UA UAL TOK.

