Definition cnt_words_exit (ra sp gp tp t0 t1 t2 s0 s1 a0 a5 a6 a7 s2 s3 s4 s5 s8 s10 t3 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (line fw B : Z) : machine_state -> Prop :=
  fun ms' => exists (a2' a3' s6' s7' s9' t6' : word) (S' : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 (line + 4 * fw)) a2' a3' (Z_to_bv 64 S') a5 a6 a7
                  s2 s3 s4 s5 s6' s7' s8 s9' s10 (Z_to_bv 64 SHB) t3 (Z_to_bv 64 0) (Z_to_bv 64 (line + 4 * fw)) t6')
             F (Z_to_bv 64 0x128a4c) fc None m (seg_rom asegs)
    /\ 0 <= S' <= B.

Lemma cnt_words : forall (k : nat) (j : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 t3 t4 t5 t6 : word) F fc (m : mem)
    (data n line fw S B tab : Z) (bs : list byte) (ws : list word),
  a1 = Z_to_bv 64 (line + 4 * j) -> t5 = Z_to_bv 64 (line + 4 * j) -> t4 = Z_to_bv 64 (fw - j) -> a4 = Z_to_bv 64 S -> s5 = Z_to_bv 64 tab ->
  Z.of_nat k = fw - j -> 0 <= j -> (1 <= k)%nat -> 0 <= S -> S + 32 * (fw - j) <= B -> B < 2^40 ->
  data <= line -> line mod 4 = 0 -> line + 4 * fw <= data + n -> 0 < data -> data mod 8 = 0 -> data + n <= 2^47 ->
  (data + n <= 0x7fff7000 \/ 0x10007fff8000 <= data) ->
  bytes_at asegs m data bs -> Z.of_nat (length bs) = n -> acc asegs m data n ->
  0 < tab -> tab mod 16 = 0 -> tab + 1024 <= 2^47 -> (tab + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= tab) ->
  u32arr asegs m tab ws -> Z.of_nat (length ws) = 256 -> tab_ok ws 256 -> acc asegs m tab 1024 ->
  mem_inv asegs m ->
  evt asegs (cnt_words_exit ra sp gp tp t0 t1 t2 s0 s1 a0 a5 a6 a7 s2 s3 s4 s5 s8 s10 t3 F fc m line fw B)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 (Z_to_bv 64 SHB) t3 t4 t5 t6)
