Definition cnt_end_exit (ra sp gp tp t0 t1 t2 s0 s1 a0 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 t3 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (B : Z) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' a3' t4' t5' t6' : word) (S' : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1' a2' a3' (Z_to_bv 64 S') a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 (Z_to_bv 64 SHB) t3 t4' t5' t6')
             F (Z_to_bv 64 0x128920) fc None m (seg_rom asegs)
    /\ 0 <= S' <= B.

Lemma cnt_endword : forall
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 t3 t4 t5 t6 : word) F fc (m : mem)
    (data n line fw S B tab : Z) (bs : list byte) (ws : list word),
  a1 = Z_to_bv 64 fw -> a0 = Z_to_bv 64 line -> a4 = Z_to_bv 64 S -> s5 = Z_to_bv 64 tab ->
  0 <= fw -> 0 <= S -> S + 32 <= B -> B < 2^40 ->
  data <= line -> line mod 4 = 0 -> line + 4 * fw + 4 <= data + n -> 0 < data -> data mod 8 = 0 -> data + n <= 2^47 ->
