Definition cnt_rows_exit (ra sp gp tp t0 t1 t2 s0 s1 a5 a7 s2 s3 s4 s5 s8 s10 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (data wpl h B : Z) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' a3' s6' s7' s9' t4' t5' t6' : word) (S' : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (data + 4 * wpl * h)) a1' a2' a3' (Z_to_bv 64 S') a5 (Z_to_bv 64 h) a7
